"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7979],{12845:e=>{e.exports=JSON.parse('{"functions":[{"name":"ensureAnimator","desc":"Returns the Animator under the character\'s Humanoid (or directly under the\\ncharacter). If there is none and the character has a Humanoid, a new Animator is\\ncreated under it.","params":[{"name":"character","desc":"","lua_type":"Model"}],"returns":[{"desc":"nil if the character has neither an Animator nor a Humanoid.","lua_type":"Animator?"}],"function_type":"static","source":{"line":27,"path":"src/PlayerUtil.luau"}},{"name":"loadAnimation","desc":"Loads an animation onto the character\'s existing Animator with `Action4`\\npriority. The janitor stops the track (with a one second fade) and destroys it\\nwhen cleaned up. This does not create an Animator; see [PlayerUtil.ensureAnimator].\\n\\n#### Example:\\n```lua\\nlocal track = PlayerUtil.loadAnimation(janitor, character, \\"rbxassetid://1234567890\\")\\nif track then\\n\\ttrack:Play()\\nend\\n```","params":[{"name":"janitor","desc":"","lua_type":"Janitor"},{"name":"character","desc":"","lua_type":"Model"},{"name":"animationId","desc":"","lua_type":"string"}],"returns":[{"desc":"nil if the character has no Animator.","lua_type":"AnimationTrack?"}],"function_type":"static","source":{"line":60,"path":"src/PlayerUtil.luau"}},{"name":"getGroupRank","desc":"Gets a player\'s rank in a group. Results are cached for 60 seconds, and a failed\\nrequest returns 0.\\n\\n#### Example:\\n```lua\\nPlayerUtil.getGroupRank(player, 1) -- 255\\n```","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"groupId","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"number"}],"function_type":"static","yields":true,"source":{"line":103,"path":"src/PlayerUtil.luau"}},{"name":"isCreator","desc":"Checks if a player created the game: the owning user, or a rank 255 member of the\\nowning group.\\n\\n#### Example:\\n```lua\\nPlayerUtil.isCreator(player) -- true\\n```","params":[{"name":"player","desc":"","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","yields":true,"source":{"line":142,"path":"src/PlayerUtil.luau"}},{"name":"getUserLevel","desc":"Gets a player\'s permission level, one of the [PlayerUtil.userLevel] values:\\n- `creator` if [PlayerUtil.isCreator] is true;\\n- in a group-owned game: `superuser` for rank 253 and above, `moderator` for\\n  rank 99 exactly, and `VIP` for ranks below 10 (including players outside the\\n  group);\\n- otherwise `premium` for Premium members, or `normal`.\\n\\n#### Example:\\n```lua\\nPlayerUtil.getUserLevel(player) -- 0\\n```","params":[{"name":"player","desc":"","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"number"}],"function_type":"static","yields":true,"source":{"line":188,"path":"src/PlayerUtil.luau"}},{"name":"getHumanoid","desc":"Gets the Humanoid of a Player\'s character, a character Model, or a Humanoid\\nitself. Warns if `object` is not an Instance.\\n\\n#### Example:\\n```lua\\nPlayerUtil.getHumanoid(player) -- Humanoid\\nPlayerUtil.getHumanoid(workspace.Zombie) -- Humanoid\\n```","params":[{"name":"object","desc":"","lua_type":"Instance?"}],"returns":[{"desc":"","lua_type":"Humanoid?"}],"function_type":"static","source":{"line":223,"path":"src/PlayerUtil.luau"}},{"name":"getCharacterHeight","desc":"Returns the height of the character\'s bounding box.","params":[{"name":"character","desc":"","lua_type":"Model"}],"returns":[{"desc":"nil if the character has no PrimaryPart.","lua_type":"number?"}],"function_type":"static","source":{"line":244,"path":"src/PlayerUtil.luau"}},{"name":"isAlive","desc":"Checks if a Player, character Model or Humanoid has a Humanoid with health above 0.\\nReturns false if no Humanoid is found.\\n\\n#### Example:\\n```lua\\nPlayerUtil.isAlive(player) -- true\\nPlayerUtil.isAlive(workspace.Zombie) -- false\\nPlayerUtil.isAlive(workspace.Part) -- false\\n```","params":[{"name":"obj","desc":"","lua_type":"Instance"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":268,"path":"src/PlayerUtil.luau"}},{"name":"hasHumanoid","desc":"Checks if a Player, character Model or Humanoid has a Humanoid.\\n\\n#### Example:\\n```lua\\nPlayerUtil.hasHumanoid(player) -- true\\nPlayerUtil.hasHumanoid(workspace.Zombie) -- true\\n```","params":[{"name":"obj","desc":"","lua_type":"Instance"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":287,"path":"src/PlayerUtil.luau"}},{"name":"getPlayerFromInstance","desc":"Gets the Player whose character contains a BasePart, by walking up its ancestors\\nuntil one holds a Humanoid. Also available as `PlayerUtil.getPlayerFromPart`.\\n\\n#### Example:\\n```lua\\nhitbox.Touched:Connect(function(part)\\n\\tlocal player = PlayerUtil.getPlayerFromInstance(part)\\nend)\\n```","params":[{"name":"instance","desc":"Anything other than a BasePart returns nil.","lua_type":"Instance?"}],"returns":[{"desc":"","lua_type":"Player?"}],"function_type":"static","source":{"line":306,"path":"src/PlayerUtil.luau"}},{"name":"getPositiontAtFeet","desc":"Gets the position at the feet of a character: its PrimaryPart\'s position, lowered\\nby half the height of the character\'s bounding box. Errors if the character has\\nno PrimaryPart.\\n\\n#### Example:\\n```lua\\nlocal effectPosition = PlayerUtil.getPositiontAtFeet(player.Character)\\n```","params":[{"name":"character","desc":"","lua_type":"Model"}],"returns":[{"desc":"","lua_type":"Vector3"}],"function_type":"static","source":{"line":336,"path":"src/PlayerUtil.luau"}},{"name":"getPlayerFromPart","desc":"Alias of [PlayerUtil.getPlayerFromInstance].","params":[{"name":"instance","desc":"","lua_type":"Instance?"}],"returns":[{"desc":"","lua_type":"Player?"}],"function_type":"static","source":{"line":350,"path":"src/PlayerUtil.luau"}},{"name":"getCharacterInformation","desc":"Returns a player\'s character, its Humanoid and its HumanoidRootPart. Returns\\nnothing if the player has no character.\\n\\n```lua\\nlocal character, humanoid, rootPart = PlayerUtil.getCharacterInformation(player)\\n```","params":[{"name":"player","desc":"","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"Model?"},{"desc":"","lua_type":"Humanoid?"},{"desc":"","lua_type":"BasePart?"}],"function_type":"static","source":{"line":366,"path":"src/PlayerUtil.luau"}},{"name":"disableOtherUi","desc":"Hides or restores every ScreenGui in the local player\'s PlayerGui, except the one\\nnamed `exception` and any whose name contains \\"Topbar\\". Hiding remembers each\\nScreenGui\'s `Enabled` state so restoring puts it back.\\n\\n```lua\\nPlayerUtil.disableOtherUi(true, \\"ShopGui\\") -- hide everything but the shop\\nPlayerUtil.disableOtherUi(false) -- restore\\n```","params":[{"name":"value","desc":"true to hide, false to restore.","lua_type":"boolean"},{"name":"exception","desc":"The name of a ScreenGui to leave alone.","lua_type":"string?"}],"returns":[],"function_type":"static","realm":["Client"],"yields":true,"source":{"line":392,"path":"src/PlayerUtil.luau"}}],"properties":[{"name":"userLevel","desc":"The permission levels returned by [PlayerUtil.getUserLevel], from lowest to\\nhighest: `normal` (0), `premium` (1), `VIP` (2), `moderator` (3), `superuser` (4)\\nand `creator` (5).\\n\\n```lua\\nif PlayerUtil.getUserLevel(player) >= PlayerUtil.userLevel.moderator then\\n\\t-- allow moderation commands\\nend\\n```","lua_type":"{ [string]: number }","source":{"line":161,"path":"src/PlayerUtil.luau"}}],"types":[],"name":"PlayerUtil","desc":"Helpers for players and their characters: humanoids, animators and animations,\\ncharacter measurements, group ranks and permission levels, and hiding player UI.","source":{"line":8,"path":"src/PlayerUtil.luau"}}')}}]);